//! Oracle-derived test vectors for the `@ stub` records of the x86_64 `msvcp_win.spec`.
//!
//! Vectors were captured by compiling the verbatim body of `__wine_spec_unimplemented_stub`
//! (`dlls/ntdll/exception.c`, lines 504-516) with `gcc -fsanitize=address,undefined -g` under
//! `target/canon/msvcp_win/`, and running the harness on the 168 `@ stub` names of the x86_64
//! build. The harness replaces `RtlRaiseException` with a recorder that longjmps out, because
//! the stub never returns. All 168 rows ran clean under ASan and UBSan, so none is excluded.

use super::*;

/// The record the harness printed for `function`. All 168 rows printed the same code, flags,
/// parameter count and module, and only the function name differs.
fn printed(function: &'static str) -> StubException {
    StubException {
        code: 0x8000_0100,
        flags: 0x01,
        number_parameters: 2,
        module: "msvcp_win.dll",
        function,
    }
}

